import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { projectedHolding, storesAt, trainingQuote, baseProduction } from '../../permutation-server/web/frontier/fland.mjs';
import { holdingModel, buildCards } from '../../permutation-server/web/frontier/screens/holding.mjs';
import { resourceModel } from '../../permutation-server/web/frontier/hud/hud.mjs';
import { outpostOffer } from '../../permutation-server/web/frontier/fconquest.mjs';

// Generated by holding-projection-gen.rs linked to the actual Rust rules crate.
// It runs Holding::settle with the program's settle_tiered adapter and
// commit_walls(now). These are outcomes, not an independent JS implementation.
const vectors=JSON.parse(readFileSync(new URL('./fixtures/holding-projection.json',import.meta.url)));
const plain=x=>JSON.parse(JSON.stringify(x,(_,v)=>typeof v==='bigint'?String(v):v));
const freeze=x=>{if(x&&typeof x==='object'){Object.values(x).forEach(freeze);Object.freeze(x);}return x;};
const resources=['Food','Wood','Stone','Ore','Horses','Gold','Science','Influence'];
const full=h=>({p:2,q:0,site:0,gen:0,order:1,faction:0,state:2,flags:0,finalTs:1n,shieldUntil:0n,reserve:Array(8).fill(0),transit:[],explore:{state:0},...h});

test('the read-only economic projection matches all Rust completion, capacity, remainder, dormancy and wall fixtures', () => {
  assert.equal(vectors.cases.length,16);
  for(const c of vectors.cases) {
    const input=freeze(structuredClone(c.input));
    const before=plain(input), projected=projectedHolding(input,c.now);
    assert.deepEqual(plain(projected),c.expected,`${c.name} at ${c.now}`);
    assert.deepEqual(input,before,'projection must not mutate decoded account state');
    assert.equal(projected.lastOwnerAction,input.lastOwnerAction,'viewing is not an owner action');
  }
});

test('projection is idempotent and polling across completion boundaries cannot change resource outcomes', () => {
  for(const c of vectors.cases) {
    const direct=projectedHolding(c.input,c.now);
    assert.deepEqual(plain(projectedHolding(direct,c.now)),plain(direct));
    const start=Number(c.input.stores[0].t0), middle=Math.floor((start+c.now)/2);
    assert.deepEqual(plain(projectedHolding(projectedHolding(c.input,middle),c.now)),plain(direct),`${c.name}: polling frequency cannot change resources`);
  }
});

test('HUD, holding tier, completed queue and build copy pricing agree as soon as construction completes', () => {
  const c=vectors.cases.find(x=>x.name==='town_base_production'&&x.now===10800), h=full(c.input);
  const fs={holdings:[h],chain:{now:()=>c.now},nowBell:18,season:{dormantAfterSecs:432000,releaseAfterSecs:864000},provinces:new Map()};
  const m=holdingModel(fs), hud=resourceModel(h,c.now), stores=storesAt(h,c.now,resources);
  assert.equal(m.holding.tier,1); assert.equal(m.facts.queue.length,0);
  assert.deepEqual(stores,m.stores); assert.equal(stores[0].value,160); assert.equal(stores[0].perHour,60); assert.equal(stores[0].cap,6000);
  assert.equal(hud.find(x=>x.resource==='Food').perHour,60);
  const farm=vectors.cases.find(x=>x.name==='first_farm'&&x.now===3660);
  const p=projectedHolding(full(farm.input),farm.now);
  const card=buildCards(p,storesAt(p,farm.now,resources),{now:farm.now})[0];
  assert.equal(card.copies,1,'a completed effect is not counted again as queued');
  assert.equal(card.secs,7200); assert.equal(card.cost[1],120);
});

test('training can use production earned after a completed building without requiring a harvest transaction first', () => {
  const c=vectors.cases.find(x=>x.name==='first_farm'),h=full(structuredClone(c.input));
  h.stores[3].value='100000';h.stores[5].value='100000';
  assert.equal(trainingQuote(h,0,100,3660,3).affordable,false);
  assert.equal(trainingQuote(h,0,100,4260,3).affordable,true);
  assert.equal(trainingQuote(h,0,100,4260,3).stores[0],61);
});

test('outpost affordability includes completed production while the raw account stays unchanged', () => {
  const production=baseProduction(1);
  const h=full({tier:1,lastOwnerAction:0n,production,upkeep:Array(8).fill(0n),stores:production.map((rate,i)=>({value:i===0?738000n:1500000n,rate,cap:6000000n,t0:0n,frac:0n})),queue:[{kind:1,arg:0,doneAt:60n,delta:12000n}]});
  const target={p:4,q:0,site:0}, s={holdings:[h],citizen:{faction:0,slots:0},season:{endBell:2016,conquestParams:{heartlandMaxRing:3,outpostTierMin:1,outpostCloseBells:24}},provinces:new Map([['4,0',{province:{siteCount:1,siteMirror:[{state:0}],conquest:[{kind:0}]}}]]),record:{openSites:100,occupiedSites:70},nowBell:6,chain:{now:()=>3600}};
  assert.equal(outpostOffer(s,target).eligible,true);
  assert.equal(h.stores[0].value,738000n); assert.equal(h.queue.length,1);
});
